"""Crucible Trace Mechanical Export Utility.

Author: Anushka Desai (anushkadesai13)
Role: Trace Export & Verification Specialist
Script: scripts/export_trace.py

Converts canonical execution JSON traces into formatted markdown excerpts
strictly following Exam Studio size limitations, prepending the verification label.
"""

from __future__ import annotations

import argparse
import json
import os
import sys
from pathlib import Path

REQUIRED_HEADER = (
    "# Trace generated by scripts/export_trace.py via mechanical truncation. "
    "No events rewritten.\n"
)


def export_trace_excerpt(input_path: str, output_path: str, max_chars: int = 12000) -> None:
    """Read full JSON trace and write mechanically truncated excerpt for submission."""
    p_in = Path(input_path)
    if not p_in.exists():
        print(f"Error: Trace file not found: {input_path}", file=sys.stderr)
        sys.exit(1)

    with open(p_in, "r", encoding="utf-8") as f:
        data = json.load(f)

    events = data.get("events", [])
    raw_json = json.dumps(events, indent=2)

    # If within limit, write full
    if len(raw_json) + len(REQUIRED_HEADER) <= max_chars:
        excerpt = REQUIRED_HEADER + "\n" + raw_json
    else:
        # Mechanical Head & Tail Truncation
        head_chars = int(max_chars * 0.6)
        tail_chars = int(max_chars * 0.35)
        head_part = raw_json[:head_chars]
        tail_part = raw_json[-tail_chars:]

        truncation_marker = (
            f"\n\n... [MECHANICAL TRUNCATION: {len(raw_json) - head_chars - tail_chars} characters omitted "
            "to comply with submission text limits; complete JSON trace preserved in repo] ...\n\n"
        )
        excerpt = REQUIRED_HEADER + head_part + truncation_marker + tail_part

    p_out = Path(output_path)
    p_out.parent.mkdir(parents=True, exist_ok=True)
    with open(p_out, "w", encoding="utf-8") as f:
        f.write(excerpt)

    print(f"Successfully exported trace to {output_path} ({len(excerpt)} chars)")


if __name__ == "__main__":
    parser = argparse.ArgumentParser(description="Export mechanical trace excerpt for submission.")
    parser.add_argument("--input", default="traces/demo_scenario_a.json", help="Path to raw trace JSON")
    parser.add_argument("--output", default="traces/scenario_a_submission_excerpt.txt", help="Output excerpt path")
    parser.add_argument("--max-chars", type=int, default=12000, help="Max characters for submission portal")
    args = parser.parse_args()

    export_trace_excerpt(args.input, args.output, args.max_chars)
